type P=(i64,i64);
fn wind(ring:&[P], px:f64, py:f64)->i32{
    // winding number via crossing count with sign, ray = +x
    let n=ring.len(); let mut w=0;
    for i in 0..n{
        let (x1,y1)=ring[i]; let (x2,y2)=ring[(i+1)%n];
        let (x1,y1,x2,y2)=(x1 as f64,y1 as f64,x2 as f64,y2 as f64);
        if y1<=py {
            if y2>py {
                // upward crossing; is p left of edge?
                let c=(x2-x1)*(py-y1)-(px-x1)*(y2-y1);
                if c>0.0 {w+=1;}
            }
        } else {
            if y2<=py {
                let c=(x2-x1)*(py-y1)-(px-x1)*(y2-y1);
                if c<0.0 {w-=1;}
            }
        }
    }
    w
}
fn area(ring:&[P])->f64{
    if ring.len()<3 {return 0.0;}
    let n=ring.len(); let mut a=0.0f64;
    // clipper order: closing edge first
    let f=|i:usize,j:usize|->f64{ ((ring[i].1+ring[j].1) as f64)*((ring[i].0-ring[j].0) as f64) };
    a+=f(n-1,0);
    for i in 0..n-1 { a+=f(i,i+1); }
    0.5*a
}
fn main(){
    let r1:Vec<P>=vec![(0,0),(50,0),(50,50),(0,50)];
    let r2:Vec<P>=vec![(25,25),(75,25),(75,75),(25,75)];
    let r3:Vec<P>=vec![(50,50),(100,50),(100,100),(50,100)];
    let rings=vec![r1.clone(),r2.clone(),r3.clone()];
    println!("areas: {} {} {}",area(&r1),area(&r2),area(&r3));
    // brute force NonZero area over unit cells
    let mut cnt=0i64;
    for x in 0..100 { for y in 0..100 {
        let px=x as f64+0.5; let py=y as f64+0.5;
        let w:i32=rings.iter().map(|r|wind(r,px,py)).sum();
        if w!=0 {cnt+=1;}
    }}
    println!("NonZero union area (unit cells) = {}",cnt);
    // even-odd
    let mut cnt2=0i64; let mut cntpos=0i64; let mut cntneg=0i64;
    for x in 0..100 { for y in 0..100 {
        let px=x as f64+0.5; let py=y as f64+0.5;
        let w:i32=rings.iter().map(|r|wind(r,px,py)).sum();
        if w&1!=0 {cnt2+=1;} if w>0 {cntpos+=1;} if w<0 {cntneg+=1;}
    }}
    println!("EvenOdd={} Positive={} Negative={}",cnt2,cntpos,cntneg);
    // claimed ring
    let g:Vec<P>=vec![(0,0),(50,0),(50,25),(75,25),(75,50),(100,50),(100,100),(50,100),(50,75),(25,75),(25,50),(0,50)];
    println!("claimed ring area = {}",area(&g));
    // verify claimed ring region == nonzero region cellwise
    let mut mismatch=0;
    for x in 0..100 { for y in 0..100 {
        let px=x as f64+0.5; let py=y as f64+0.5;
        let w:i32=rings.iter().map(|r|wind(r,px,py)).sum();
        let wg=wind(&g,px,py);
        if (w!=0)!=(wg!=0) {mismatch+=1;}
    }}
    println!("cell mismatches vs claimed ring = {}",mismatch);
    // winding of 4 quadrants at (50,50)
    for (dx,dy,nm) in [(-0.5,-0.5,"SW"),(0.5,-0.5,"SE"),(0.5,0.5,"NE"),(-0.5,0.5,"NW")] {
        let w:i32=rings.iter().map(|r|wind(r,50.0+dx,50.0+dy)).sum();
        println!("quadrant {} w={}",nm,w);
    }
}
