type P=(i64,i64);
fn cross(o:P,a:P,b:P)->i128{ ((a.0-o.0) as i128)*((b.1-o.1) as i128)-((a.1-o.1) as i128)*((b.0-o.0) as i128) }
fn on(a:P,b:P,p:P)->bool{ cross(a,b,p)==0 && p.0>=a.0.min(b.0)&&p.0<=a.0.max(b.0)&&p.1>=a.1.min(b.1)&&p.1<=a.1.max(b.1) }
fn main(){
    let rings:Vec<Vec<P>>=vec![
      vec![(0,0),(50,0),(50,50),(0,50)],
      vec![(25,25),(75,25),(75,75),(25,75)],
      vec![(50,50),(100,50),(100,100),(50,100)]];
    let mut segs:Vec<(usize,usize,P,P)>=vec![];
    for (ri,r) in rings.iter().enumerate(){ let n=r.len(); for i in 0..n { segs.push((ri,i,r[i],r[(i+1)%n])); } }
    for i in 0..segs.len(){ for j in i+1..segs.len(){
        let (r1,i1,a,b)=segs[i]; let (r2,i2,c,d)=segs[j];
        let d1=cross(a,b,c); let d2=cross(a,b,d); let d3=cross(c,d,a); let d4=cross(c,d,b);
        let collinear = d1==0&&d2==0;
        if collinear {
            // measure overlap length along the line
            let pts=[(a,"a"),(b,"b"),(c,"c"),(d,"d")];
            let inter:Vec<_> = pts.iter().filter(|(p,_)| on(a,b,*p)&&on(c,d,*p)).map(|(p,n)|(*p,*n)).collect();
            if !inter.is_empty(){
                let xs:Vec<i64>=inter.iter().map(|(p,_)|p.0).collect();
                let ys:Vec<i64>=inter.iter().map(|(p,_)|p.1).collect();
                let len2=(xs.iter().max().unwrap()-xs.iter().min().unwrap()).pow(2)+(ys.iter().max().unwrap()-ys.iter().min().unwrap()).pow(2);
                println!("COLLINEAR r{}e{} {:?}-{:?} vs r{}e{} {:?}-{:?}  overlapLen^2={}",r1,i1,a,b,r2,i2,c,d,len2);
            }
        } else if ((d1>0)!=(d2>0)||d1==0||d2==0) && ((d3>0)!=(d4>0)||d3==0||d4==0) {
            // proper intersection point (rational)
            let x1=a.0 as f64; let y1=a.1 as f64; let x2=b.0 as f64; let y2=b.1 as f64;
            let x3=c.0 as f64; let y3=c.1 as f64; let x4=d.0 as f64; let y4=d.1 as f64;
            let den=(x2-x1)*(y4-y3)-(y2-y1)*(x4-x3);
            if den!=0.0 {
                let t=((x3-x1)*(y4-y3)-(y3-y1)*(x4-x3))/den;
                let u=((x3-x1)*(y2-y1)-(y3-y1)*(x2-x1))/den;
                if t>=0.0&&t<=1.0&&u>=0.0&&u<=1.0 {
                    let px=x1+t*(x2-x1); let py=y1+t*(y2-y1);
                    let kind = if (t==0.0||t==1.0)&&(u==0.0||u==1.0) {"VERTEX-VERTEX"} else if t==0.0||t==1.0||u==0.0||u==1.0 {"T-JUNCTION"} else {"TRANSVERSAL"};
                    println!("{} at ({},{}) : r{}e{} {:?}-{:?} (t={}) vs r{}e{} {:?}-{:?} (u={})",kind,px,py,r1,i1,a,b,t,r2,i2,c,d,u);
                }
            }
        }
    }}
}
